// function getMax(arr) mein array do
// Agar array nahi ya empty: null
// Agar koi non-number: "Invalid element"
// Warna maximum value do

solution:
function getMax(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return null
  if (arr.some(item => typeof item !== "number")) return "Invalid element"
  return Math.max(...arr)
}
